class Solution {
public:
    int search(const ArrayReader& reader, int target) {
        int left = 0;
        int right = 1;
        while (reader.get(right) < target) {
            left = right + 1;
            right *= 2;
        }
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int value = reader.get(mid);
            if (value == target) {
                return mid;
            }
            if (value < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
};
